const results = [];
for (const item of items) {
  const binary = item.binary || {};
  const keys = Object.keys(binary).filter(k => k === 'File_Upload' || k.startsWith('File_Upload_'));
  for (const key of keys) {
    results.push({ json: item.json, binary: { File_Upload: binary[key] } });
  }
}
return results;
